<?php
namespace App\Http\Controllers;use App\Models\{AcceptanceRun,ResearchObservation,Survey,ValidationRun};use App\Services\{AcceptanceAuditService,ScientificValidationService};use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\View\View;
class ValidationController extends Controller{public function index(Request$r):View{abort_unless($r->user()->can('audit.view'),403);return view('validation.index',['validationRuns'=>ValidationRun::with('survey')->latest('executed_at')->paginate(20),'acceptanceRuns'=>AcceptanceRun::latest('executed_at')->limit(10)->get(),'surveys'=>Survey::latest()->get()]);}public function scientific(Request$r,Survey$survey,ScientificValidationService$service):JsonResponse{abort_unless($r->user()->can('insights.review'),403);$d=$r->validate(['holdout_percent'=>'nullable|numeric|between:10,30','power'=>'nullable|numeric|between:1,5']);return response()->json($service->validate($survey,$r->user()->id,$d['holdout_percent']??20,$d['power']??2),201);}public function acceptance(Request$r,AcceptanceAuditService$service):JsonResponse{abort_unless($r->user()->can('audit.view'),403);$result=$service->run();$run=AcceptanceRun::create(['executed_by'=>$r->user()->id,'status'=>$result['status'],'passed_checks'=>$result['passed'],'failed_checks'=>$result['failed'],'checks'=>$result['checks'],'environment'=>['app_env'=>app()->environment(),'php'=>PHP_VERSION,'laravel'=>app()->version(),'database'=>config('database.default'),'queue'=>config('queue.default')],'executed_at'=>now()]);return response()->json($run,201);}public function observation(Request$r):JsonResponse{abort_unless($r->user()->can('surveys.manage'),403);$d=$r->validate(['survey_id'=>'nullable|exists:surveys,id','observation_type'=>'required|in:device,environment,intervention,limitation,comparison','device_name'=>'nullable|string|max:150','device_platform'=>'nullable|string|max:150','environmental_conditions'=>'nullable|array','observation'=>'required|string|max:5000','observed_at'=>'required|date']);$d['recorded_by']=$r->user()->id;return response()->json(ResearchObservation::create($d),201);}}
